class Solution {
public:
    void pattern20(int n) {
        for(int i=1; i<=n; i++){
            // Left stars
            for(int j=0; j<i; j++){
                cout << "*";
            }
            // Middle spaces
            for(int j=2*(n-i); j>0; j--){
                cout << " ";
            }
            // Right stars
            for(int j=0; j<i; j++){
                cout << "*";
            }
            cout << endl;
        }

        // Lower half
        for(int i=1; i<n; i++){
            // Left stars
            for(int j=0; j<n-i; j++){
                cout << "*";
            }
            // Middle spaces
            for(int j=0; j<2*i; j++){
                cout << " ";
            }
            // Right stars
            for(int j=0; j<n-i; j++){
                cout << "*";
            }
            cout << endl;
        }
    }

};

